# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C6（v4 新域 11 簇+直答）

补：重组家庭/留守/网瘾/追星/直播/隐私/养老/城乡/医患/消费/躺平
"""
def patch(path):
    src = open(path, encoding="utf-8").read()

    # ===== 簇：插在「概念形成」簇前 =====
    anchor_c = '    "概念形成": ["概念形成", "原型理论", "样例理论", "概念是怎么形成的"],'
    new_c = '''    "重组家庭": ["重组家庭", "继父", "继母", "继子女", "不是亲生的",
                "当成亲生的", "重组家庭的孩子", "继子女接受", "新家庭",
                "后爸", "后妈", "重组"],
    "留守儿童": ["留守儿童", "外出打工", "爷爷奶奶带", "父母带",
                "弥补对孩子的亏欠", "留守儿童心理", "留守孩子",
                "打工和孩子", "孩子缺陪伴"],
    "游戏成瘾": ["一玩游戏就停不下来", "沉迷手机游戏", "沉迷游戏", "游戏瘾",
                "堵不如疏", "让孩子玩", "戒掉游戏", "游戏和学业",
                "网瘾", "游戏上瘾", "打游戏", "孩子玩游戏"],
    "追星": ["疯狂追星", "追星花钱", "追星浪费", "不让孩子追星", "看待孩子追星",
            "追星的热情", "追星", "追偶像", "偶像崇拜", "饭圈"],
    "直播消费": ["看直播买东西", "直播带货", "忍不住买", "直播真的便宜",
                "不买直播", "理性消费", "直播套路", "冲动消费",
                "直播电商", "直播间", "主播"],
    "数据隐私": ["APP什么权限都要", "数据被谁拿走", "数据换便利", "隐私重要",
                "方便重要", "数据归谁", "隐私泄露", "个人信息",
                "大数据杀熟", "隐私", "数据安全"],
    "养老社会": ["养老金不够用", "养老金", "老了谁来照顾", "延迟退休",
                "坑年轻人", "规划自己的养老", "老龄化", "老年社会",
                "养老靠谁", "退休金"],
    "城乡流动": ["打工多年没归属感", "外地孩子上学", "城市资源有限",
                "回老家发展", "流动人口", "融入城市", "户籍",
                "北漂", "打工人", "农民工", "落户"],
    "医患关系": ["医患关系紧张", "看病难", "看病贵", "医生忙", "患者抱怨",
                "花了钱没治好", "医患理解", "看病不再难", "挂号难",
                "医患", "医院"],
    "消费主义": ["总想买新东西", "赚钱不花", "留着下崽", "拉动经济",
                "分清需要和想要", "消费主义", "买买买", "剁手",
                "双十一", "购物欲", "冲动购物"],
    "内卷躺平": ["越来越多人躺平", "躺平", "内卷", "不负责任", "不努力",
                "好生活", "卷和躺", "奋斗还是躺平", "努力也难翻身",
                "卷不动", "佛系"],'''
    assert anchor_c in src
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    # ===== 直答：插在「概念形成」直答前 =====
    anchor_d = '    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'
    new_d = '''    "重组家庭": "重组家庭难相处，是『血缘认同』和『新关系建立』的时间差——继子女对继父母没有天然信任，任何管教都被解读为『不是亲生的所以针对我』。真相：①孩子不是敏感是警惕——亲爹妈打骂是爱，继父说一句就是『外人的恶意』，同样的行为在不同关系里解读完全不同；②别急着当亲生的——强行亲近（『以后我就是你爸』）会触发抵触，关系要慢慢来，先做朋友再做长辈；③亲生的那个也别委屈——重组后亲爸妈容易补偿过度（溺爱/偏心），反而制造新的不公平；④减少冲突的机制——规则前置（谁管什么/奖惩一致）、各自空间（别逼孩子叫爸妈）、不站队（别让孩子当传话筒）。核心：重组家庭不是复制原生家庭，是建立『新的家庭文化』——给时间，别强求，边界清晰比感情到位更重要",
    "留守儿童": "留守儿童是『经济发展』和『家庭完整』的矛盾产物——父母外出打工是家庭收入的需要，代价是孩子成长中缺陪伴。真相：①留守儿童的心理问题不是『缺钱』是『缺连接』——被忽视感/被抛弃感（爸妈是不是不要我了），比物质匮乏更伤；②爷爷奶奶能管生活管不了心理——老人给温饱，给不了同龄人式的理解与引导（青春期尤其明显）；③父母带vs老人带的差别——不在日常照顾，在『情感回应』：父母在身边的及时回应（抱抱/说说话）是安全感来源，视频通话补不了全部但能补一部分。破解：①定期高质量陪伴——不是时长是质量：固定视频时间/每年团聚/让孩子参与家庭决策（被需要的感受）；②替代性依恋——帮孩子建立稳定的替代关系（信任的老师/朋友/亲戚），一个可靠的大人能缓冲很多；③别让愧疚变成溺爱——外出父母常用物质补偿（要啥买啥），反而教不会孩子延迟满足。核心：弥补亏欠不是买礼物，是让孩子确认『爸妈在乎我这个人』",
    "游戏成瘾": "孩子沉迷游戏停不下来，是『游戏的设计』碾压『学习的激励』——游戏有即时反馈（每步都有奖励/升级/成就），学习是延迟满足（考完试才知道结果）；游戏是精心设计的成瘾机制（随机奖励/社交攀比/进度条），不是孩子意志力差。真相：①游戏满足真实需求——成就感（学习里没有）、社交（现实孤独）、掌控感（现实被安排）——游戏是需求的替代品，不解决需求只禁游戏会转移（短视频/小说）；②『堵不如疏』有道理但不全对——完全放任也不行，关键是『替代满足』：给孩子能获得成就感的其他出口（运动/兴趣/竞赛），游戏自然降级。破解：①限时+契约——不是没收是约定（做完作业玩一小时），给掌控感（孩子自己定计划）；②替代奖励——把学习也设计成有反馈的小目标（即时表扬/积分）；③警惕戒断反应——突然没收会爆发冲突，逐步减量+补替代活动。核心：戒的不是游戏，是让现实重新变得有吸引力",
    "追星": "孩子疯狂追星，是青春期的『自我投射』——偶像承载了孩子想成为的样子（优秀/被爱/自由），追星是自我认同的练习，不是不务正业。真相：①追星满足什么——归属感（粉丝群体）、理想自我（偶像=想成为的人）、情感寄托（安全距离的爱，不会受伤）；②花钱离谱的根源——饭圈营造『不花钱就是不爱』的攀比，孩子被群体裹挟（应援/打榜），本质是社交压力不是真爱；③不让孩子追星太专制——禁止只会转入地下（更失控），也切断了了解孩子的窗口。引导：①不否定只讨论——问问『你喜欢他什么』（借机了解孩子的价值观），把追星变成亲子话题；②设金钱边界——给零花钱额度，超了要说明（教预算）；③引导正途——追星热情可以转化为技能（剪辑/写作/组织应援=项目管理），『热爱偶像』可以变成『成为那样的人』（努力学习/练习才艺）。核心：追星是成长的练习场，引导它而不消灭它",
    "直播消费": "看直播忍不住买东西，是『即时冲动』被『销售话术』精准触发——限时抢购（制造稀缺）、主播砍价（制造占便宜感）、弹幕刷屏（制造从众），每句『家人们』都在降低你的理性。真相：①直播便宜是错觉——主播的『全网最低价』多数是话术，很多商品直播价和日常活动价差不多；②买的是情绪不是需要——直播间营造狂欢氛围，下单是情绪冲动不是需求判断（买了不用=最贵）；③不买直播落伍是错觉——落伍的是消费方式，不是生活品质，按需购买才是高级。破解：①下单前停三秒——问『没有这个直播，我会买吗』（划走直播间再决定）；②设购物冷静期——想要的先放购物车24小时，多数冲动会消；③算『使用频率』——单价÷预计用几次=真实成本，用一次200块=贵；④卸载冲动源头——取关带货主播/少刷购物直播间。核心：直播是商场+肾上腺素，理性消费从『关掉冲动』开始",
    "数据隐私": "APP什么权限都要、数据被拿走，是『免费服务的真实成本是数据』——你以为免费用，其实用隐私付费（个性化广告/画像）。真相：①权限要多的逻辑——位置/通讯录/麦克风多数不是功能必需，是数据采集（卖给广告商/风控/模型训练）；②『数据换便利』是半真半假——个性化推荐确实方便，但『只要授权才能用』是绑架（明明不需要通讯录的也要）；③数据归谁——法律上归用户（个人信息保护法），实际上归平台（你同意了用户协议=让渡了使用权），这本身就是不公平的默认设置。保护三招：①权限最小化——只给必要权限，不需要的拒绝（导航才给位置/不用语音别给麦克风）；②隐私设置——关掉个性化广告/数据共享，虽然麻烦但有效；③数据源控制——少用『一键登录』（手机号授权关联一切），关键账号单独密码。核心：数据是你的数字指纹，能少给就少给——便利是有价的，只是账单不是现金",
    "养老社会": "养老金不够用、老龄化加剧，是『交钱的人少、领钱的人多』的人口结构矛盾——出生率下降（年轻人少）叠加寿命延长（老人多），现收现付制的养老金池子自然紧张。真相：①养老金是代际转移——现在老人领的是现在年轻人交的，等我们老了领的是下一代交的，人口结构一变（少子化）必然承压；②延迟退休的逻辑——不是坑年轻人，是『交的时间更长+领的时间更短』来缓解池子压力，但对体力劳动者是实打实的负担（70岁还要搬砖）；③生孩子的意义不是养老——靠子女养老在现代社会不现实（孩子有自己的压力），但『养儿防老』的焦虑会推动生育。应对：①自己养老三支柱——社保（基本盘）+企业年金/个人养老金（补充）+个人储蓄投资（主力），别只靠第一支柱；②健康是最大的养老金——保持身体比存钱更省（医疗是老人最大开销）；③社会层面——延迟退休要配套（高龄就业岗位/适老化改造），只延不配是转嫁。核心：养老不能全指望国家或子女，自己的三支柱要趁早搭",
    "城乡流动": "打工多年没归属感、孩子上学难，是『人在城市贡献』vs『制度不认你』的矛盾——交了税、建了城，但户籍/教育/医疗把流动人口挡在外面。真相：①没归属感的根源——不是城市冷漠，是『留不下』的预期：没户口没房，随时可能被挤出，人不会对一个随时会离开的地方产生归属；②外地孩子上学难的机制——学位按户籍分配，随迁子女要么回老家（留守）要么上私立（贵），这是资源的排他性分配；③城市资源有限的辩解半真半假——学位确实有限，但『外地人挤占了本地资源』是伪命题（流动人口也是建设者/纳税人）。破解：①制度层——户籍改革/随迁子女入学逐步放开（已经在做，但慢）；②个人层——城市乡村的选择不是二选一：城市给机会，乡村给归属，『县城/新一线』是中间态（有发展又相对友好）；③心理层——归属感可以自己建：融入社区/参加活动/找到城市里的熟人网络，归属是关系不是户口。核心：城乡矛盾本质是发展权分配，个人的破局是找到适合自己的中间地带",
    "医患关系": "医患关系紧张、看病难，是『生命期望』vs『医疗现实』的落差——患者要『一定治好』，医学给的是『尽力而为』；信息不对称（患者不懂医）+资源稀缺（挂号难/排队久）把落差变成冲突。真相：①医患冲突的深层——不是医生坏或患者刁，是制度压力转嫁：医生超负荷（半天看60个病人）没时间解释，患者等了3小时只看5分钟觉得被敷衍，双方都是受害者；②看病贵不是医生赚了——药价/检查费是体系成本，医生的劳动报酬被严重低估（所以才开检查单/多开药补偿）；③『花了钱没治好』的愤怒——是『花钱=买结果』的误解，医疗买的是『尽力』不是『包好』，但没人提前告诉患者这个预期。破解：①患者侧——看病前做准备（症状/病史/想问的问题写下来）、理解医学的局限（医生不是神）、合理维权（投诉/举证，不闹事）；②医生侧——多一句解释（『为什么做这个检查』）能化解大半误解；③制度侧——分级诊疗（小病社区大病医院）/医生多点执业/医患沟通培训。核心：医患要联手对抗的是疾病和制度，不是彼此",
    "消费主义": "东西越买越多却不快乐、总想买新的，是『消费主义把幸福外包给了物品』——广告/社交告诉你『买了它你就幸福/被爱/成功』，但物品带来的快乐衰减极快（享乐适应：新手机三天就无感），于是只能再买（永动机）。真相：①买买买的驱动力——不是需要是身份焦虑（用物品证明自己）、情绪补偿（不开心就买）、从众（别人有我也要）；②消费拉动经济是宏观逻辑——个人适度消费当然好，但『消费主义』是微观绑架：让你把自我价值绑在物品上；③需要和想要的区分——需要是功能（能解决什么问题），想要是情绪（买了我更开心/更体面），90%的『想要』经不起追问。破解：①购物前灵魂三问——『我真的需要吗？会常用吗？不买会怎样？』；②延迟满足——想要的放清单，一周后还想要再买（多数会消失）；③用体验替代物品——旅行/学习/和朋友吃饭，体验的快乐比物品持久（记忆不会折旧）；④记账看见去向——钱去哪了可视化，冲动自然减少。核心：幸福不拒绝消费，拒绝的是用消费代替生活",
    "内卷躺平": "越来越多人躺平、内卷蔓延，是『付出-回报失衡』的集体反应——努力的人越来越多（同质化竞争），但蛋糕没变大（上升通道收窄），边际努力换不来边际回报（996也难买房），躺平是理性止损不是堕落。真相：①内卷的本质——不是努力变多，是『无差异努力』变多：大家做一样的事（刷题/加班）争有限的资源，边际收益递减（多刷100小时只多1分）；②躺平是对内卷的负反馈——当努力不改变结果，放弃努力是理性选择（系统平衡），指责躺平的人忽略了这个信号；③『不努力还想好生活』的误区——躺平者不是不想要好生活，是不信努力能换来（预期管理），给希望比给道德批判有效。破解：①个人——避开同质化竞争（差异化：稀缺技能/交叉领域），卷的方向不对努力白费；②『卷』和『躺』的中间态——不是全卷或全躺，是选择性用力（重要的事卷，次要的事躺，保存心力）；③社会——内卷的解药是分配（教育/住房/机会公平），个人只能先保心态。核心：内卷是系统问题，个人破局靠差异化——既不盲卷也不全躺，找到自己的生态位",
    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'''
    assert anchor_d in src
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

patch(r"C:\Users\FuRongJun\AppData\Local\Programs\Python\Python310\lib\site-packages\wisdom\semantic_translate.py")
